import { GoogleGenAI } from "@google/genai";

// Initialize Gemini Client
// WARNING: In a production environment, API calls should be proxied through a backend
// to protect the API key. For this client-side demo, we use the env variable directly.
const apiKey = process.env.API_KEY || '';

const ai = new GoogleGenAI({ apiKey });

export const generateExplanation = async (topic: string, context: string): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `اشرح لي هذا الموضوع القانوني الجزائري بشكل مبسط للطلاب:
      الموضوع: ${topic}
      السياق: ${context}

      اجعل الشرح باللغة العربية الواضحة مع أمثلة من الواقع الجزائري.`,
    });
    return response.text || "لم يتم العثور على إجابة.";
  } catch (error) {
    console.error("Error generating explanation:", error);
    return "حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.";
  }
};

export const generateResearchPlan = async (title: string): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `اقترح خطة بحث (Plan de recherche) لمذكرة تخرج حول الموضوع التالي: "${title}".
      يجب أن تكون الخطة ثنائية (مبحثين، كل مبحث مطلبين) وفق المنهجية القانونية الجزائرية.`,
    });
    return response.text || "لم يتم إنشاء خطة.";
  } catch (error) {
    console.error("Error generating plan:", error);
    return "حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.";
  }
};

export const chatWithLegalAI = async (message: string, history: {role: string, parts: {text: string}[]}[]): Promise<string> => {
    if (!apiKey) return "عذراً، الخدمة غير متوفرة حالياً.";

    try {
        const chat = ai.chats.create({
            model: 'gemini-2.5-flash',
            history: history,
            config: {
                systemInstruction: "أنت مساعد قانوني ذكي متخصص في القانون الجزائري (DZ LAW HUB). أجب باللغة العربية أو الدارجة الجزائرية المهذبة. قدم استشارات عامة دائماً مع التنويه بأنك ذكاء اصطناعي ويجب استشارة محامٍ في القضايا الحساسة."
            }
        });

        const result = await chat.sendMessage({ message });
        return result.text || "لا توجد إجابة";
    } catch (error) {
        console.error("Chat Error", error);
        return "حدث خطأ في النظام.";
    }
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useRef, useEffect } from 'react';
import { Send, AlertTriangle, Bot, User, RefreshCw } from 'lucide-react';
import { chatWithLegalAI } from '../services/geminiService';
import { ChatMessage } from '../types';

const AIAssistant: React.FC = () => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'model',
      text: 'مرحباً بك في المستشار القانوني الذكي. كيف يمكنني مساعدتك اليوم في القانون الجزائري؟',
      timestamp: new Date()
    }
  ]);
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    // Prepare history for Gemini
    const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
    }));

    const responseText = await chatWithLegalAI(userMsg.text, history);

    const botMsg: ChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: responseText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, botMsg]);
    setLoading(false);
  };

  return (
    <div className="container mx-auto px-4 py-8 h-[calc(100vh-64px)] flex flex-col">
      <div className="flex-1 bg-white dark:bg-slate-800 rounded-2xl shadow-xl border border-slate-200 dark:border-slate-700 overflow-hidden flex flex-col">

        {/* Header */}
        <div className="bg-primary/10 p-4 border-b dark:border-slate-700 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-primary p-2 rounded-full">
              <Bot className="w-6 h-6 text-white" />
            </div>
            <div>
              <h2 className="font-bold text-lg dark:text-white">المستشار القانوني DZ</h2>
              <p className="text-xs text-slate-500 dark:text-slate-400">مدعوم بالذكاء الاصطناعي (Gemini)</p>
            </div>
          </div>
          <div className="bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 text-xs px-3 py-1 rounded-full flex items-center gap-1 border border-yellow-200 dark:border-yellow-800">
            <AlertTriangle className="w-3 h-3" />
            تنبيه: المعلومات للأغراض التعليمية فقط
          </div>
        </div>

        {/* Chat Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-6">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-start' : 'justify-end'}`}>
              <div className={`max-w-[80%] md:max-w-[70%] rounded-2xl p-4 ${
                msg.role === 'user' 
                  ? 'bg-primary text-white rounded-br-none' 
                  : 'bg-slate-100 dark:bg-slate-700 text-slate-800 dark:text-slate-200 rounded-bl-none'
              }`}>
                <div className="flex items-center gap-2 mb-1 opacity-70 text-xs">
                  {msg.role === 'user' ? <User className="w-3 h-3" /> : <Bot className="w-3 h-3" />}
                  <span>{msg.role === 'user' ? 'أنت' : 'المساعد'}</span>
                </div>
                <div className="whitespace-pre-wrap leading-relaxed">
                  {msg.text}
                </div>
              </div>
            </div>
          ))}
          {loading && (
            <div className="flex justify-end">
              <div className="bg-slate-100 dark:bg-slate-700 rounded-2xl rounded-bl-none p-4 flex items-center gap-2">
                <RefreshCw className="w-4 h-4 animate-spin text-slate-500" />
                <span className="text-sm text-slate-500">جاري التحليل والكتابة...</span>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 bg-slate-50 dark:bg-slate-900 border-t dark:border-slate-700">
          <div className="flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="اكتب سؤالك القانوني هنا..."
              className="flex-1 bg-white dark:bg-slate-800 border dark:border-slate-700 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-primary dark:text-white"
            />
            <button 
              onClick={handleSend}
              disabled={loading || !input.trim()}
              className="bg-primary hover:bg-blue-600 disabled:bg-slate-400 text-white p-3 rounded-xl transition shadow-lg"
            >
              <Send className="w-5 h-5 rtl:rotate-180" />
            </button>
          </div>
          <p className="text-center text-xs text-slate-400 mt-2">
            يرجى التأكد من صحة النصوص القانونية واستشارة محامٍ مختص في القضايا الرسمية.
          </p>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

import React, { useState } from 'react';
import { LESSONS } from '../constants';
import { BookOpen, Sparkles, ChevronDown } from 'lucide-react';
import { generateExplanation } from '../services/geminiService';

const Lessons: React.FC = () => {
  const [activeYear, setActiveYear] = useState<1 | 2 | 3>(1);
  const [aiModalOpen, setAiModalOpen] = useState(false);
  const [modalContent, setModalContent] = useState({ title: '', text: '' });
  const [loadingAi, setLoadingAi] = useState(false);

  const filteredLessons = LESSONS.filter(l => l.year === activeYear);

  const handleExplain = async (title: string, summary: string) => {
    setAiModalOpen(true);
    setModalContent({ title: `شرح: ${title}`, text: 'جاري استدعاء الذكاء الاصطناعي...' });
    setLoadingAi(true);

    const explanation = await generateExplanation(title, summary);

    setModalContent({ title: `شرح: ${title}`, text: explanation });
    setLoadingAi(false);
  };

  return (
    <div className="container mx-auto px-4 py-12">
      <h1 className="text-3xl font-bold mb-8 text-center dark:text-white">الدروس والمحاضرات</h1>

      {/* Tabs */}
      <div className="flex justify-center gap-4 mb-12">
        {[1, 2, 3].map((year) => (
          <button
            key={year}
            onClick={() => setActiveYear(year as 1|2|3)}
            className={`px-6 py-3 rounded-full font-bold transition-all ${
              activeYear === year 
                ? 'bg-primary text-white shadow-lg shadow-blue-500/30' 
                : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-700'
            }`}
          >
            السنة {year === 1 ? 'الأولى' : year === 2 ? 'الثانية' : 'الثالثة'}
          </button>
        ))}
      </div>

      {/* Grid */}
      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8">
        {filteredLessons.map((lesson) => (
          <div key={lesson.id} className="bg-white dark:bg-slate-800 rounded-2xl shadow-md border border-slate-100 dark:border-slate-700 overflow-hidden flex flex-col h-full hover:shadow-xl transition duration-300">
            <div className="p-6 flex-1">
              <div className="flex items-center gap-2 mb-4">
                <span className="bg-blue-100 dark:bg-blue-900/50 text-primary text-xs font-bold px-2 py-1 rounded">LMD</span>
                <h3 className="text-xl font-bold dark:text-white">{lesson.title}</h3>
              </div>
              <p className="text-slate-600 dark:text-slate-300 mb-6 text-sm leading-relaxed line-clamp-3">
                {lesson.summary}
              </p>

              <div className="space-y-4">
                <div className="bg-slate-50 dark:bg-slate-900 p-3 rounded-lg">
                  <h4 className="font-bold text-sm mb-2 dark:text-slate-200">نقاط أساسية:</h4>
                  <ul className="list-disc list-inside text-xs text-slate-500 dark:text-slate-400">
                    {lesson.keyPoints.map((kp, i) => <li key={i}>{kp}</li>)}
                  </ul>
                </div>
              </div>
            </div>

            <div className="p-4 border-t dark:border-slate-700 bg-slate-50 dark:bg-slate-900/50">
              <button 
                onClick={() => handleExplain(lesson.title, lesson.summary)}
                className="w-full bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white py-2 rounded-xl text-sm font-bold flex items-center justify-center gap-2 transition shadow"
              >
                <Sparkles className="w-4 h-4" />
                فسّرلي أكثر يا الذكاء الاصطناعي
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* AI Modal */}
      {aiModalOpen && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-2xl max-w-2xl w-full max-h-[80vh] flex flex-col">
            <div className="p-6 border-b dark:border-slate-700 flex justify-between items-center">
              <h3 className="text-xl font-bold flex items-center gap-2 dark:text-white">
                <BotIcon className="w-6 h-6 text-primary" />
                {modalContent.title}
              </h3>
              <button onClick={() => setAiModalOpen(false)} className="text-slate-400 hover:text-slate-600">✕</button>
            </div>
            <div className="p-6 overflow-y-auto flex-1">
              {loadingAi ? (
                <div className="flex flex-col items-center justify-center py-12">
                   <div className="w-12 h-12 border-4 border-primary border-t-transparent rounded-full animate-spin mb-4"></div>
                   <p className="text-slate-500">الذكاء الاصطناعي يكتب الشرح...</p>
                </div>
              ) : (
                <div className="prose dark:prose-invert max-w-none whitespace-pre-wrap leading-loose">
                  {modalContent.text}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

