export default Lessons;

import React, { useState } from 'react';
import { FLASHCARDS } from '../constants';
import { RefreshCw, Bookmark } from 'lucide-react';

const Flashcards: React.FC = () => {
  const [flippedCards, setFlippedCards] = useState<Set<string>>(new Set());

  const toggleFlip = (id: string) => {
    const newFlipped = new Set(flippedCards);
    if (newFlipped.has(id)) {
      newFlipped.delete(id);
    } else {
      newFlipped.add(id);
    }
    setFlippedCards(newFlipped);
  };

  return (
    <div className="container mx-auto px-4 py-12">
       <div className="flex justify-between items-end mb-8">
        <div>
           <h1 className="text-3xl font-bold dark:text-white mb-2">بطاقات المراجعة</h1>
           <p className="text-slate-500 dark:text-slate-400">انقر على البطاقة لرؤية التعريف والسند القانوني</p>
        </div>
        <button className="flex items-center gap-2 text-primary hover:underline font-bold text-sm">
          <Bookmark className="w-4 h-4" /> البطاقات المحفوظة
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        {FLASHCARDS.map((card) => (
          <div 
            key={card.id} 
            className="h-64 cursor-pointer perspective-1000 group"
            onClick={() => toggleFlip(card.id)}
          >
            <div className={`relative w-full h-full transition-transform duration-700 transform-style-3d ${flippedCards.has(card.id) ? 'rotate-y-180' : ''}`}>

              {/* Front */}
              <div className="absolute w-full h-full backface-hidden bg-white dark:bg-slate-800 rounded-2xl shadow-lg border border-slate-200 dark:border-slate-700 flex flex-col items-center justify-center p-6 text-center hover:border-primary transition">
                <span className="text-xs font-bold text-primary tracking-widest uppercase mb-4">مصطلح قانوني</span>
                <h3 className="text-2xl font-black dark:text-white">{card.term}</h3>
                <div className="mt-8 text-slate-400 text-xs flex items-center gap-1">
                  <RefreshCw className="w-3 h-3" /> انقر للقلب
                </div>
              </div>

              {/* Back */}
