import React, { useState } from 'react';
import { QUIZ_CATEGORIES } from '../constants';
import { CheckCircle, XCircle, Trophy, RefreshCcw } from 'lucide-react';

const Quizzes: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);

  const category = QUIZ_CATEGORIES.find(c => c.id === activeCategory);

  const handleAnswer = (optionIndex: number) => {
    setSelectedOption(optionIndex);
    // Add small delay to show selection
    setTimeout(() => {
        if (category && optionIndex === category.questions[currentQuestionIndex].correctAnswer) {
            setScore(s => s + 1);
        }

        if (category && currentQuestionIndex < category.questions.length - 1) {
            setCurrentQuestionIndex(prev => prev + 1);
            setSelectedOption(null);
        } else {
            setShowResult(true);
        }
    }, 500);
  };

  const resetQuiz = () => {
    setActiveCategory(null);
    setCurrentQuestionIndex(0);
    setScore(0);
    setShowResult(false);
    setSelectedOption(null);
  };

  if (!activeCategory) {
    return (
      <div className="container mx-auto px-4 py-12">
        <h1 className="text-3xl font-bold mb-8 text-center dark:text-white">اختبر معلوماتك القانونية</h1>
        <div className="grid md:grid-cols-3 gap-6">
          {QUIZ_CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              className="bg-white dark:bg-slate-800 p-8 rounded-2xl shadow hover:shadow-xl transition border border-transparent hover:border-primary text-center group"
            >
              <div className="w-16 h-16 bg-slate-100 dark:bg-slate-700 rounded-full mx-auto mb-6 flex items-center justify-center text-2xl group-hover:bg-primary group-hover:text-white transition">
                ?
              </div>
              <h3 className="text-xl font-bold dark:text-white mb-2">{cat.name}</h3>
              <p className="text-slate-500 text-sm">{cat.questions.length} أسئلة</p>
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (showResult && category) {
    const percentage = (score / category.questions.length) * 100;
    return (
      <div className="container mx-auto px-4 py-12 flex justify-center">
        <div className="bg-white dark:bg-slate-800 p-10 rounded-3xl shadow-2xl text-center max-w-md w-full">
          <Trophy className={`w-20 h-20 mx-auto mb-6 ${percentage >= 50 ? 'text-yellow-400' : 'text-slate-400'}`} />
          <h2 className="text-3xl font-black mb-2 dark:text-white">
            {percentage >= 50 ? 'أحسنت!' : 'حاول مرة أخرى'}
          </h2>
          <p className="text-slate-500 mb-8">لقد أنهيت اختبار {category.name}</p>

          <div className="text-5xl font-bold text-primary mb-8">
            {score}/{category.questions.length}
          </div>

          <button 
            onClick={resetQuiz}
            className="w-full bg-slate-900 dark:bg-slate-700 text-white py-3 rounded-xl font-bold hover:bg-slate-800 flex items-center justify-center gap-2"
          >
            <RefreshCcw className="w-4 h-4" />
            اختبار آخر
          </button>
        </div>
      </div>
    );
  }

  if (category) {
    const question = category.questions[currentQuestionIndex];
    const progress = ((currentQuestionIndex) / category.questions.length) * 100;

    return (
      <div className="container mx-auto px-4 py-12 max-w-2xl">
        <div className="mb-6 flex items-center justify-between text-sm text-slate-500">
           <span>سؤال {currentQuestionIndex + 1} من {category.questions.length}</span>
           <span>{category.name}</span>
        </div>

        {/* Progress Bar */}
        <div className="h-2 bg-slate-200 dark:bg-slate-700 rounded-full mb-8 overflow-hidden">
            <div className="h-full bg-primary transition-all duration-300" style={{ width: `${progress}%` }}></div>
        </div>

        <div className="bg-white dark:bg-slate-800 rounded-2xl shadow-lg p-8">
            <h2 className="text-2xl font-bold mb-8 leading-relaxed dark:text-white">{question.question}</h2>

            <div className="space-y-3">
                {question.options.map((opt, idx) => (
                    <button
                        key={idx}
                        onClick={() => handleAnswer(idx)}
                        disabled={selectedOption !== null}
                        className={`w-full text-right p-4 rounded-xl border-2 transition-all flex items-center justify-between
                        ${selectedOption === idx 
                            ? 'border-primary bg-blue-50 dark:bg-blue-900/20' 
                            : 'border-slate-100 dark:border-slate-700 hover:border-slate-300 dark:hover:border-slate-600 dark:text-slate-200'}
                        `}
                    >
                        <span>{opt}</span>
                        {selectedOption === idx && <CheckCircle className="w-5 h-5 text-primary" />}
                    </button>
                ))}
            </div>
        </div>
      </div>
    );
  }

  return null;
};

export default Quizzes;

