                }`}>
                    {msg.role === 'user' ? <User className="w-5 h-5" /> : <Bot className="w-5 h-5" />}
                </div>

                {/* Bubble */}
                <div className={`p-5 rounded-lg shadow-sm text-sm leading-7 ${
                  msg.role === 'user' 
                    ? 'bg-white dark:bg-slate-800 text-slate-800 dark:text-slate-200 border-r-4 border-primary' 
                    : 'bg-white dark:bg-slate-900 text-slate-800 dark:text-slate-200 border border-slate-200 dark:border-slate-800'
                }`}>
                  <div className="whitespace-pre-wrap font-medium">
                    {msg.text}
