import React, { useState } from 'react';
import { QUIZ_CATEGORIES } from '../constants';
import { CheckCircle, XCircle, Trophy, RefreshCcw, ArrowRight } from 'lucide-react';

const Quizzes: React.FC = () => {
  const [activeCategory, setActiveCategory] = useState<string | null>(null);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [selectedOption, setSelectedOption] = useState<number | null>(null);

  const category = QUIZ_CATEGORIES.find(c => c.id === activeCategory);

  const handleAnswer = (optionIndex: number) => {
    setSelectedOption(optionIndex);
    setTimeout(() => {
        if (category && optionIndex === category.questions[currentQuestionIndex].correctAnswer) {
            setScore(s => s + 1);
        }

        if (category && currentQuestionIndex < category.questions.length - 1) {
            setCurrentQuestionIndex(prev => prev + 1);
            setSelectedOption(null);
        } else {
            setShowResult(true);
        }
    }, 500);
  };

  const resetQuiz = () => {
    setActiveCategory(null);
    setCurrentQuestionIndex(0);
    setScore(0);
    setShowResult(false);
    setSelectedOption(null);
  };

  if (!activeCategory) {
    return (
      <div className="container mx-auto px-4 py-12">
        <div className="text-center mb-16">
            <h1 className="text-4xl font-black text-secondary dark:text-white mb-4">قيّم معلوماتك</h1>
            <p className="text-slate-500 max-w-lg mx-auto">مجموعة اختبارات تفاعلية مصممة لتقييم استيعابك للمفاهيم القانونية الأساسية في مختلف التخصصات.</p>
        </div>

        <div className="grid md:grid-cols-3 gap-8">
          {QUIZ_CATEGORIES.map((cat) => (
            <button
              key={cat.id}
              onClick={() => setActiveCategory(cat.id)}
              className="bg-white dark:bg-slate-900 p-8 rounded-lg shadow-sm hover:shadow-xl transition duration-300 border border-slate-200 dark:border-slate-800 hover:border-primary group text-right"
            >
              <span className="text-xs font-bold text-primary tracking-widest uppercase mb-4 block">اختبار تفاعلي</span>
              <h3 className="text-2xl font-bold text-secondary dark:text-white mb-4 group-hover:translate-x-[-4px] transition-transform">{cat.name}</h3>
              <div className="flex justify-between items-center text-slate-500 text-sm border-t border-slate-100 dark:border-slate-800 pt-4">
                 <span>{cat.questions.length} أسئلة</span>
                 <ArrowRight className="w-4 h-4 group-hover:text-primary transition-colors rtl:rotate-180" />
              </div>
            </button>
          ))}
        </div>
      </div>
    );
  }

  if (showResult && category) {
    const percentage = (score / category.questions.length) * 100;
    return (
      <div className="container mx-auto px-4 py-12 flex justify-center">
        <div className="bg-white dark:bg-slate-900 p-12 rounded-lg shadow-2xl text-center max-w-md w-full border border-slate-200 dark:border-slate-800">
          <div className="inline-flex justify-center items-center w-20 h-20 rounded-full bg-slate-50 dark:bg-slate-800 mb-6">
            <Trophy className={`w-10 h-10 ${percentage >= 50 ? 'text-primary' : 'text-slate-400'}`} />
          </div>
          <h2 className="text-2xl font-black mb-2 text-secondary dark:text-white">
            {percentage >= 50 ? 'نتيجة ممتازة' : 'يمكنك التحسن'}
          </h2>
          <p className="text-slate-500 mb-8 text-sm">أتممت اختبار {category.name}</p>

          <div className="text-6xl font-black text-secondary dark:text-white mb-8">
            {score}<span className="text-2xl text-slate-400">/{category.questions.length}</span>
          </div>

          <button 
            onClick={resetQuiz}
            className="w-full bg-primary hover:bg-primary-dark text-secondary font-bold py-4 rounded transition flex items-center justify-center gap-2"
          >
            <RefreshCcw className="w-4 h-4" />
            العودة للقائمة
          </button>
        </div>
      </div>
    );
  }

  if (category) {
    const question = category.questions[currentQuestionIndex];
    const progress = ((currentQuestionIndex) / category.questions.length) * 100;

    return (
      <div className="container mx-auto px-4 py-12 max-w-2xl">
        <div className="mb-8 flex items-center justify-between text-xs font-bold uppercase tracking-widest text-slate-400">
           <span>Question {currentQuestionIndex + 1} / {category.questions.length}</span>
           <span>{category.name}</span>
        </div>

        {/* Progress Bar */}
        <div className="h-1 bg-slate-200 dark:bg-slate-800 rounded-full mb-10 overflow-hidden">
            <div className="h-full bg-primary transition-all duration-500 ease-out" style={{ width: `${progress}%` }}></div>
        </div>

        <div className="bg-white dark:bg-slate-900 rounded-lg shadow-lg p-10 border border-slate-200 dark:border-slate-800">
            <h2 className="text-2xl font-bold mb-10 leading-relaxed text-secondary dark:text-white">{question.question}</h2>

            <div className="space-y-4">
                {question.options.map((opt, idx) => (
                    <button
                        key={idx}
                        onClick={() => handleAnswer(idx)}
                        disabled={selectedOption !== null}
                        className={`w-full text-right p-5 rounded border transition-all flex items-center justify-between group
                        ${selectedOption === idx 
                            ? 'border-primary bg-primary/10 text-primary-dark font-bold' 
                            : 'border-slate-200 dark:border-slate-700 hover:border-primary dark:hover:border-primary hover:bg-slate-50 dark:hover:bg-slate-800 text-secondary dark:text-slate-300'}
                        `}
                    >
                        <span>{opt}</span>
                        {selectedOption === idx && <CheckCircle className="w-5 h-5 text-primary" />}
                    </button>
                ))}
            </div>
        </div>
      </div>
    );
  }

  return null;
};

export default Quizzes;

