export const generateExplanation = async (topic: string, context: string): Promise<string> => {
  if (!apiKey) return "عذراً، مفتاح API غير متوفر.";

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: `اشرح لي هذا الموضوع القانوني الجزائري بشكل مبسط للطلاب:
      الموضوع: ${topic}
      السياق: ${context}

      اجعل الشرح باللغة العربية الواضحة مع أمثلة من الواقع الجزائري.`,
      config: {
        tools: [{ googleSearch: {} }],
      }
    });

    // Check for grounding metadata (sources)
    const groundingMetadata = response.candidates?.[0]?.groundingMetadata;
    let text = response.text || "لم يتم العثور على إجابة.";

    if (groundingMetadata?.groundingChunks) {
        const sources = groundingMetadata.groundingChunks
            .filter((c: any) => c.web?.uri)
            .map((c: any) => `• [${c.web.title}](${c.web.uri})`)
            .join('\n');

        if (sources) {
            text += `\n\n**المصادر:**\n${sources}`;
        }
    }

    return text;
  } catch (error) {
    console.error("Error generating explanation:", error);
    return "حدث خطأ أثناء الاتصال بالذكاء الاصطناعي.";
  }
};

