    setLoading(true);
    setPlanOutput({ id, text: 'جاري إنشاء هيكل البحث...' });
    const plan = await generateResearchPlan(title);
    setPlanOutput({ id, text: plan });
    setLoading(false);
  };

  const handleCorrectPlan = async () => {
    if(!correctionTitle.trim() || !userPlan.trim()) return;

