import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, RefreshCw, Sparkles, BookOpen } from 'lucide-react';
import { chatWithLegalAI } from '../services/geminiService';
import { ChatMessage } from '../types';

const AIAssistant: React.FC = () => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'model',
      text: 'مرحباً يا بطل! 🎓\nأنا رفيقك الدراسي الذكي. اسألني عن أي غموض في دروسك، أو اطلب مني أمثلة توضيحية، وسأساعدك فوراً.\n\nجرب أن تسأل: "ما الفرق بين الباطل والفاسد؟" أو "اشرح لي أركان العقد بمثال".',
      timestamp: new Date()
    }
  ]);
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: input,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
    }));

    const responseText = await chatWithLegalAI(userMsg.text, history);

    const botMsg: ChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: responseText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, botMsg]);
    setLoading(false);
  };

  // Helper function to render text with markdown-style links [text](url)
  const renderMessageContent = (text: string) => {
    const parts = [];
    let lastIndex = 0;
    // Regex for [title](url)
    const regex = /\[([^\]]+)\]\((https?:\/\/[^\)]+)\)/g;
    let match;

    while ((match = regex.exec(text)) !== null) {
      if (match.index > lastIndex) {
        parts.push(text.substring(lastIndex, match.index));
      }
      parts.push(
        <a 
          key={match.index} 
          href={match[2]} 
          target="_blank" 
          rel="noopener noreferrer" 
          className="text-primary hover:text-primary-light underline font-bold mx-1"
        >
          {match[1]}
        </a>
      );
      lastIndex = regex.lastIndex;
    }

    if (lastIndex < text.length) {
      parts.push(text.substring(lastIndex));
    }

    return parts.length > 0 ? parts : text;
  };

  return (
    <div className="container mx-auto px-4 py-6 h-[calc(100vh-80px)] flex flex-col max-w-4xl">
      <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl shadow-xl shadow-slate-200/50 dark:shadow-none border border-slate-100 dark:border-slate-800 overflow-hidden flex flex-col">

        {/* Header */}
        <div className="bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-slate-800 p-4 flex items-center gap-4">
            <div className="w-12 h-12 bg-gradient-to-br from-primary to-purple-500 rounded-full flex items-center justify-center shadow-lg shadow-primary/20">
                <Sparkles className="w-6 h-6 text-white" />
            </div>
            <div>
                <h2 className="font-bold text-slate-800 dark:text-white">المرافق الدراسي</h2>
                <div className="flex items-center gap-1.5">
                    <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                    <span className="text-xs text-slate-500 font-medium">متصل الآن - جاهز للمساعدة</span>
                </div>
            </div>
        </div>

        {/* Chat Area */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50 dark:bg-slate-950">
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end animate-slide-in-right' : 'justify-start animate-slide-in-left'}`}>
              <div className={`flex gap-3 max-w-[85%] md:max-w-[75%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>

                {/* Avatar */}
                <div className={`w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 mt-1 shadow-sm ${
                    msg.role === 'user' ? 'bg-slate-200 dark:bg-slate-700 text-slate-600' : 'bg-primary text-white'
                }`}>
                    {msg.role === 'user' ? <User className="w-4 h-4" /> : <Bot className="w-4 h-4" />}
                </div>

                {/* Bubble */}
                <div className={`p-4 rounded-2xl text-sm leading-relaxed shadow-sm ${
                  msg.role === 'user' 
                    ? 'bg-primary text-white rounded-tr-none' 
                    : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 rounded-tl-none border border-slate-100 dark:border-slate-700'
                }`}>
                  <div className="whitespace-pre-wrap">
                    {renderMessageContent(msg.text)}
                  </div>
                </div>

              </div>
            </div>
          ))}

          {loading && (
            <div className="flex justify-start animate-slide-in-left">
               <div className="flex gap-3">
                   <div className="w-8 h-8 rounded-full bg-primary text-white flex items-center justify-center flex-shrink-0 mt-1">
                        <Bot className="w-4 h-4" />
                   </div>
                   <div className="bg-white dark:bg-slate-800 px-4 py-3 rounded-2xl rounded-tl-none border border-slate-100 dark:border-slate-700 flex items-center gap-2">
                       <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce"></span>
                       <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-100"></span>
                       <span className="w-1.5 h-1.5 bg-slate-400 rounded-full animate-bounce delay-200"></span>
                   </div>
               </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>

        {/* Input Area */}
        <div className="p-4 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
          <div className="relative flex items-center gap-2">
            <button className="p-3 text-slate-400 hover:text-primary hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition">
                <BookOpen className="w-5 h-5" />
            </button>
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="اكتب سؤالك هنا..."
              className="flex-1 bg-slate-100 dark:bg-slate-800 border-0 rounded-xl px-4 py-3 focus:outline-none focus:ring-2 focus:ring-primary/50 text-slate-800 dark:text-white placeholder:text-slate-400"
            />
            <button 
              onClick={handleSend}
              disabled={loading || !input.trim()}
              className="bg-primary hover:bg-primary-light disabled:bg-slate-300 disabled:cursor-not-allowed text-white p-3 rounded-xl transition shadow-lg shadow-primary/20"
            >
              <Send className="w-5 h-5 rtl:rotate-180" />
            </button>
          </div>
          <p className="text-center text-[10px] text-slate-400 mt-2">
            المعلومات المقدمة للأغراض التعليمية. تأكد دائماً من المراجع الرسمية.
          </p>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;

import React, { useState, useRef, useEffect } from 'react';
import { Send, Bot, User, RefreshCw, Sparkles, BookOpen, Trash2, StopCircle, ArrowUp } from 'lucide-react';
import { chatWithLegalAI } from '../services/geminiService';
import { ChatMessage } from '../types';

const SUGGESTIONS = [
  { text: "ما الفرق بين الباطل والفاسد؟", icon: "⚖️" },
  { text: "شرح أركان القرار الإداري", icon: "📜" },
  { text: "كيفية إعداد خطة بحث مذكرة تخرج", icon: "🎓" },
  { text: "الفرق بين الجناية والجنحة والمخالفة", icon: "gavel" },
];

const AIAssistant: React.FC = () => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState<ChatMessage[]>([
    {
      id: 'welcome',
      role: 'model',
      text: 'مرحباً يا بطل! 🎓\nأنا رفيقك الدراسي الذكي في "DZ LAW HUB". \nاسألني عن أي غموض في دروسك، أو اطلب مني أمثلة توضيحية، وسأساعدك فوراً.',
      timestamp: new Date()
    }
  ]);
  const [loading, setLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, loading]);

  const handleSend = async (textOverride?: string) => {
    const textToSend = textOverride || input;
    if (!textToSend.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      text: textToSend,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMsg]);
    setInput('');
    setLoading(true);

    // Prepare history for API
    const history = messages.map(m => ({
        role: m.role,
        parts: [{ text: m.text }]
    }));

    const responseText = await chatWithLegalAI(userMsg.text, history);

    const botMsg: ChatMessage = {
      id: (Date.now() + 1).toString(),
      role: 'model',
      text: responseText,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, botMsg]);
    setLoading(false);
  };

  const handleClearChat = () => {
    setMessages([
        {
          id: 'welcome',
          role: 'model',
          text: 'مرحباً مجدداً! 🎓\nكيف يمكنني مساعدتك في دراستك القانونية اليوم؟',
          timestamp: new Date()
        }
    ]);
  };

  // Helper function to render text with markdown-style links [text](url)
  const renderMessageContent = (text: string) => {
    const parts = [];
    let lastIndex = 0;
    // Regex for [title](url)
    const regex = /\[([^\]]+)\]\((https?:\/\/[^\)]+)\)/g;
    let match;

    while ((match = regex.exec(text)) !== null) {
      if (match.index > lastIndex) {
        parts.push(text.substring(lastIndex, match.index));
      }
      parts.push(
        <a 
          key={match.index} 
          href={match[2]} 
          target="_blank" 
          rel="noopener noreferrer" 
          className="text-primary hover:text-primary-light underline font-bold mx-1"
        >
          {match[1]}
        </a>
      );
      lastIndex = regex.lastIndex;
    }

    if (lastIndex < text.length) {
      parts.push(text.substring(lastIndex));
    }

    return parts.length > 0 ? parts : text;
  };

  return (
    <div className="container mx-auto px-4 py-6 h-[calc(100vh-80px)] flex flex-col max-w-5xl">
      <div className="flex-1 bg-white dark:bg-slate-900 rounded-3xl shadow-2xl shadow-slate-200/50 dark:shadow-none border border-slate-200 dark:border-slate-800 overflow-hidden flex flex-col relative">

        {/* Header */}
        <div className="bg-white/90 dark:bg-slate-900/90 backdrop-blur-sm border-b border-slate-100 dark:border-slate-800 p-4 flex items-center justify-between z-10 sticky top-0">
            <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
                    <Sparkles className="w-6 h-6 text-white" />
                </div>
                <div>
                    <h2 className="font-bold text-lg text-slate-800 dark:text-white">المرافق الدراسي</h2>
                    <div className="flex items-center gap-1.5">
                        <span className="w-2 h-2 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></span>
                        <span className="text-xs text-slate-500 font-medium">Gemini 2.5 Pro</span>
                    </div>
                </div>
            </div>

            <button 
                onClick={handleClearChat}
                className="p-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-xl transition-all"
                title="مسح المحادثة"
            >
                <Trash2 className="w-5 h-5" />
            </button>
        </div>

        {/* Chat Area */}
        <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-8 bg-slate-50 dark:bg-slate-950 scroll-smooth">

          {/* Messages */}
          {messages.map((msg) => (
            <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end animate-slide-in-right' : 'justify-start animate-slide-in-left'}`}>
              <div className={`flex gap-4 max-w-[85%] md:max-w-[75%] ${msg.role === 'user' ? 'flex-row-reverse' : 'flex-row'}`}>

                {/* Avatar */}
                <div className={`w-10 h-10 rounded-full flex items-center justify-center flex-shrink-0 mt-1 shadow-md border-2 border-white dark:border-slate-800 ${
                    msg.role === 'user' ? 'bg-slate-200 dark:bg-slate-700 text-slate-600' : 'bg-gradient-to-br from-indigo-500 to-purple-600 text-white'
                }`}>
                    {msg.role === 'user' ? <User className="w-5 h-5" /> : <Bot className="w-5 h-5" />}
                </div>

                {/* Bubble */}
                <div className="flex flex-col gap-1">
                    <span className={`text-[10px] font-bold text-slate-400 px-1 ${msg.role === 'user' ? 'text-right' : 'text-left'}`}>
                        {msg.role === 'user' ? 'أنت' : 'المساعد الذكي'}
                    </span>
                    <div className={`p-4 md:p-5 rounded-3xl text-sm md:text-base leading-loose shadow-sm ${
                    msg.role === 'user' 
                        ? 'bg-primary text-white rounded-tr-sm shadow-indigo-500/20' 
                        : 'bg-white dark:bg-slate-800 text-slate-700 dark:text-slate-200 rounded-tl-sm border border-slate-200 dark:border-slate-700'
                    }`}>
                    <div className="whitespace-pre-wrap">
                        {renderMessageContent(msg.text)}
                    </div>
                    </div>
                </div>

              </div>
            </div>
          ))}

          {/* Loading Indicator */}
          {loading && (
            <div className="flex justify-start animate-slide-in-left">
               <div className="flex gap-4">
                   <div className="w-10 h-10 rounded-full bg-gradient-to-br from-indigo-500 to-purple-600 text-white flex items-center justify-center flex-shrink-0 mt-1 shadow-md border-2 border-white dark:border-slate-800">
                        <Bot className="w-5 h-5" />
                   </div>
                   <div className="bg-white dark:bg-slate-800 px-6 py-4 rounded-3xl rounded-tl-sm border border-slate-200 dark:border-slate-700 flex items-center gap-2 shadow-sm">
                       <span className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce"></span>
                       <span className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-100"></span>
                       <span className="w-2 h-2 bg-indigo-400 rounded-full animate-bounce delay-200"></span>
                   </div>
               </div>
            </div>
          )}

          <div ref={messagesEndRef} />
        </div>

        {/* Suggestions (Visible if chat is empty or short) */}
        {messages.length === 1 && !loading && (
            <div className="absolute bottom-24 left-0 w-full px-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-w-3xl mx-auto">
                    {SUGGESTIONS.map((s, idx) => (
                        <button 
                            key={idx}
                            onClick={() => handleSend(s.text)}
                            className="bg-white/80 dark:bg-slate-800/80 backdrop-blur-sm p-3 rounded-xl border border-slate-200 dark:border-slate-700 hover:border-primary hover:text-primary dark:hover:text-primary text-slate-600 dark:text-slate-300 text-sm font-medium transition-all shadow-sm flex items-center gap-3 text-right"
                        >
                            <span className="text-xl">{s.icon}</span>
                            {s.text}
                        </button>
                    ))}
                </div>
            </div>
        )}

        {/* Input Area */}
        <div className="p-4 md:p-6 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800">
          <div className="relative flex items-end gap-3 max-w-4xl mx-auto bg-slate-50 dark:bg-slate-800/50 p-2 rounded-[2rem] border border-slate-200 dark:border-slate-700 focus-within:ring-2 focus-within:ring-primary/20 focus-within:border-primary/50 transition-all">

            <button className="p-3 text-slate-400 hover:text-primary hover:bg-slate-200 dark:hover:bg-slate-700 rounded-full transition self-end">
                <BookOpen className="w-5 h-5" />
            </button>

            <textarea
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSend();
                  }
              }}
              placeholder="اكتب سؤالك القانوني هنا..."
              className="flex-1 bg-transparent border-0 py-3.5 px-2 focus:outline-none focus:ring-0 text-slate-800 dark:text-white placeholder:text-slate-400 resize-none max-h-32 min-h-[50px]"
              rows={1}
            />

            <button 
              onClick={() => handleSend()}
              disabled={loading || !input.trim()}
              className={`p-3 rounded-full transition-all shadow-lg flex-shrink-0 mb-1 ${
                  loading || !input.trim() 
                  ? 'bg-slate-200 dark:bg-slate-700 text-slate-400 cursor-not-allowed shadow-none' 
                  : 'bg-primary hover:bg-primary-light text-white shadow-primary/30 transform hover:scale-105'
              }`}
            >
              {loading ? <StopCircle className="w-5 h-5 animate-pulse" /> : <ArrowUp className="w-5 h-5" />}
            </button>
          </div>
          <p className="text-center text-[10px] text-slate-400 mt-3 font-medium">
            DZ LAW HUB AI يمكن أن يرتكب أخطاء. يرجى التحقق من المعلومات المهمة.
          </p>
        </div>
      </div>
    </div>
  );
};

export default AIAssistant;
